import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { LucideIcon } from "lucide-react";

export interface NavItem {
  label: string;
  href: string;
}

export interface ServiceItem {
  title: string;
  description: string;
  icon: LucideIcon;
  color: string;
  colSpan?: string;
  bg?: string;
  textColor?: string;
}

export interface PortfolioItem {
  id: number;
  title: string;
  category: string;
  imageUrl: string;
}

export interface Testimonial {
  id: number;
  name: string;
  role: string;
  company: string;
  content: string;
  avatar: string;
}

import React from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import ServicesBento from './components/ServicesBento';
import PortfolioDeck from './components/PortfolioDeck';
import Testimonials from './components/Testimonials';
import ContactSection from './components/ContactSection';
import Footer from './components/Footer';

const App: React.FC = () => {
  return (
    <div className="flex flex-col min-h-screen w-full overflow-x-hidden font-sans">
      <Navbar />
      <main className="flex-grow">
        <Hero />
        <ServicesBento />
        <PortfolioDeck />
        <Testimonials />
        <ContactSection />
      </main>
      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Menu, X, Rocket } from 'lucide-react';
import { NavItem } from '../types';

const NAV_ITEMS: NavItem[] = [
  { label: 'Services', href: '#services' },
  { label: 'Work', href: '#work' },
  { label: 'About', href: '#about' },
  { label: 'Reviews', href: '#reviews' },
];

const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled
          ? 'bg-white/80 backdrop-blur-md shadow-sm py-4'
          : 'bg-transparent py-6'
      }`}
    >
      <div className="container mx-auto px-6 flex items-center justify-between">
        {/* Logo */}
        <a href="#" className="flex items-center gap-2 group">
          <div className="bg-brand-600 p-2 rounded-xl text-white transform transition-transform group-hover:rotate-12">
            <Rocket size={20} fill="currentColor" />
          </div>
          <span className="text-xl font-bold tracking-tight text-slate-900">
            LocalPulse
          </span>
        </a>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-8">
          {NAV_ITEMS.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className="text-sm font-medium text-slate-600 hover:text-brand-600 transition-colors"
            >
              {item.label}
            </a>
          ))}
          <a
            href="#contact"
            className="px-5 py-2.5 bg-brand-900 text-white text-sm font-semibold rounded-full hover:bg-brand-800 transition-colors shadow-lg shadow-brand-200"
          >
            Get Started
          </a>
        </div>

        {/* Mobile Menu Button */}
        <button
          className="md:hidden p-2 text-slate-600 hover:text-brand-600"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 w-full bg-white border-b border-slate-100 p-6 md:hidden shadow-xl flex flex-col gap-4 animate-in slide-in-from-top-2">
          {NAV_ITEMS.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className="text-lg font-medium text-slate-600 hover:text-brand-600"
              onClick={() => setIsMobileMenuOpen(false)}
            >
              {item.label}
            </a>
          ))}
          <a
            href="#contact"
            className="w-full text-center px-5 py-3 bg-brand-600 text-white font-semibold rounded-lg"
            onClick={() => setIsMobileMenuOpen(false)}
          >
            Get Started
          </a>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React from 'react';
import { motion } from 'framer-motion';
import { ArrowUpRight } from 'lucide-react';
import { PortfolioItem } from '../types';

const PORTFOLIO_ITEMS: PortfolioItem[] = [
  { id: 1, title: 'Bean & Brew', category: 'Coffee Shop', imageUrl: 'https://picsum.photos/seed/coffee/600/800' },
  { id: 2, title: 'Urban Fit', category: 'Gym & Fitness', imageUrl: 'https://picsum.photos/seed/fitness/600/800' },
  { id: 3, title: 'Green Scape', category: 'Landscaping', imageUrl: 'https://picsum.photos/seed/garden/600/800' },
  { id: 4, title: 'Pure Dental', category: 'Healthcare', imageUrl: 'https://picsum.photos/seed/dentist/600/800' },
  { id: 5, title: 'Tech Fix', category: 'Repair Shop', imageUrl: 'https://picsum.photos/seed/tech/600/800' },
];

const PortfolioDeck: React.FC = () => {
  return (
    <section id="work" className="py-24 bg-slate-50 overflow-hidden">
      <div className="container mx-auto px-6 text-center mb-12">
        <h2 className="text-4xl font-bold text-slate-900 mb-4">A place to display your masterpiece.</h2>
        <p className="text-slate-600 max-w-xl mx-auto">
          We treat every project like art. Here are a few local businesses we've helped transform recently.
        </p>
      </div>

      {/* Mobile Grid View */}
      <div className="md:hidden container mx-auto px-6 grid gap-6">
        {PORTFOLIO_ITEMS.map((item) => (
          <div key={item.id} className="relative group rounded-2xl overflow-hidden aspect-[4/3]">
            <img src={item.imageUrl} alt={item.title} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent flex flex-col justify-end p-6">
              <span className="text-brand-300 text-sm font-medium">{item.category}</span>
              <h3 className="text-white text-xl font-bold">{item.title}</h3>
            </div>
          </div>
        ))}
      </div>

      {/* Desktop Fanned Deck */}
      <div className="hidden md:flex justify-center items-center h-[600px] relative w-full max-w-6xl mx-auto perspective-1000">
        {PORTFOLIO_ITEMS.map((item, index) => {
          // Calculate offset to fan them out nicely
          // Center is index 2.
          const offset = index - 2; 

          return (
            <motion.div
              key={item.id}
              initial={{ rotate: offset * 5, x: offset * 120, y: Math.abs(offset) * 20 }}
              whileHover={{ 
                y: -40, 
                rotate: 0, 
                zIndex: 10, 
                scale: 1.1,
                transition: { duration: 0.3 }
              }}
              className="absolute w-80 h-[450px] bg-white rounded-3xl shadow-2xl overflow-hidden border-4 border-white cursor-pointer origin-bottom"
              style={{
                zIndex: index === 2 ? 5 : 5 - Math.abs(offset), // Center on top
              }}
            >
              <div className="relative h-full w-full group">
                <img 
                  src={item.imageUrl} 
                  alt={item.title} 
                  className="w-full h-full object-cover" 
                />

                {/* Overlay on Hover */}
                <div className="absolute inset-0 bg-brand-900/90 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col items-center justify-center text-center p-6">
                   <h3 className="text-2xl font-bold text-white mb-2">{item.title}</h3>
                   <p className="text-brand-200 mb-6">{item.category}</p>
                   <button className="flex items-center gap-2 text-white border border-white/30 px-6 py-2 rounded-full hover:bg-white hover:text-brand-900 transition-all">
                     View Case Study <ArrowUpRight size={16} />
                   </button>
                </div>
              </div>
            </motion.div>
          );
        })}
      </div>

      <div className="text-center mt-12 md:mt-0">
         <a href="#" className="inline-flex items-center text-brand-600 font-semibold hover:text-brand-700">
            See all projects <ArrowUpRight className="ml-1 w-4 h-4" />
         </a>
      </div>
    </section>
  );
};

export default PortfolioDeck;

