import React, { useState, useEffect } from 'react';
import { Menu, X, Rocket } from 'lucide-react';
import { NavItem, Page } from '../types';

interface NavbarProps {
  currentPage: Page;
  onNavigate: (page: Page) => void;
}

const NAV_ITEMS: NavItem[] = [
  { label: 'Services', href: '#services', action: 'scroll' },
  { label: 'Work', href: '#work', action: 'page' }, 
  { label: 'About', href: '#about', action: 'page' }, 
  { label: 'Reviews', href: '#reviews', action: 'scroll' },
];

const Navbar: React.FC<NavbarProps> = ({ currentPage, onNavigate }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNavClick = (e: React.MouseEvent, item: NavItem) => {
    e.preventDefault();
    setIsMobileMenuOpen(false);

    // Handle 'page' actions
    if (item.action === 'page') {
      if (item.label === 'Work') {
        onNavigate('gallery');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else if (item.label === 'About') {
        onNavigate('about');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } else {
      // Handle 'scroll' actions
      if (currentPage !== 'home') {
        onNavigate('home');
        // Allow time for render then scroll
        setTimeout(() => {
          const element = document.querySelector(item.href);
          element?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      } else {
         const element = document.querySelector(item.href);
         element?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const handleLogoClick = (e: React.MouseEvent) => {
    e.preventDefault();
    onNavigate('home');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const isDarkNav = currentPage === 'gallery' || currentPage === 'about' || currentPage === 'start-project';

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled || isDarkNav
          ? 'bg-white/80 backdrop-blur-md shadow-sm py-4'
          : 'bg-transparent py-6'
      }`}
    >
      <div className="container mx-auto px-6 flex items-center justify-between">
        {/* Logo */}
        <a href="#" onClick={handleLogoClick} className="flex items-center gap-2 group">
          <div className="bg-brand-600 p-2 rounded-xl text-white transform transition-transform group-hover:rotate-12">
            <Rocket size={20} fill="currentColor" />
          </div>
          <span className="text-xl font-bold tracking-tight text-slate-900">
            LocalPulse
          </span>
        </a>

        {/* Desktop Nav */}
        <div className="hidden md:flex items-center gap-8">
          {NAV_ITEMS.map((item) => (
            <a
              key={item.label}
              href={item.href}
              onClick={(e) => handleNavClick(e, item)}
              className={`text-sm font-medium transition-colors ${
                (currentPage === 'gallery' && item.label === 'Work') || (currentPage === 'about' && item.label === 'About')
                  ? 'text-brand-600 font-bold' 
                  : 'text-slate-600 hover:text-brand-600'
              }`}
            >
              {item.label}
            </a>
          ))}
          <button
            onClick={() => {
               onNavigate('start-project');
               window.scrollTo({ top: 0, behavior: 'smooth' });
            }}
            className="px-5 py-2.5 bg-brand-900 text-white text-sm font-semibold rounded-full hover:bg-brand-800 transition-colors shadow-lg shadow-brand-200"
          >
            Get Started
          </button>
        </div>

        {/* Mobile Menu Button */}
        <button
          className="md:hidden p-2 text-slate-600 hover:text-brand-600"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 w-full bg-white border-b border-slate-100 p-6 md:hidden shadow-xl flex flex-col gap-4 animate-in slide-in-from-top-2">
          {NAV_ITEMS.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className="text-lg font-medium text-slate-600 hover:text-brand-600"
              onClick={(e) => handleNavClick(e, item)}
            >
              {item.label}
            </a>
          ))}
          <button
            className="w-full text-center px-5 py-3 bg-brand-600 text-white font-semibold rounded-lg"
            onClick={(e) => {
               e.preventDefault();
               setIsMobileMenuOpen(false);
               onNavigate('start-project');
               window.scrollTo({ top: 0, behavior: 'smooth' });
            }}
          >
            Get Started
          </button>
        </div>
      )}
    </nav>
  );
};

