                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                                <Mail size={16} /> Email Address
                            </label>
                            <input 
                              required
                              type="email" 
                              value={formData.email}
                              onChange={(e) => setFormData({...formData, email: e.target.value})}
                              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:border-brand-500 focus:ring-2 focus:ring-brand-200 outline-none transition-all"
                              placeholder="jane@example.com"
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') e.preventDefault();
                              }}
                            />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                            <Lock size={16} /> Password
                        </label>
                        <input 
                          required
                          type="password" 
                          value={formData.password}
                          onChange={(e) => setFormData({...formData, password: e.target.value})}
                          className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:border-brand-500 focus:ring-2 focus:ring-brand-200 outline-none transition-all"
                          placeholder="Create a strong password"
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') e.preventDefault();
                          }}
                        />
                        <p className="text-xs text-slate-400">Must be at least 8 characters long.</p>
                      </div>

                      <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 text-sm text-slate-600 flex gap-3">
                         <div className="mt-0.5">
                             <input 
                               type="checkbox" 
                               required 
                               checked={formData.terms}
                               onChange={(e) => setFormData({...formData, terms: e.target.checked})}
                               className="w-4 h-4 rounded border-slate-300 text-brand-600 focus:ring-brand-500" 
                             />
                         </div>
                         <p>I agree to the <a href="#" className="text-brand-600 font-bold hover:underline">Terms of Service</a> and <a href="#" className="text-brand-600 font-bold hover:underline">Privacy Policy</a>.</p>
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Navigation Actions */}
              <div className="flex items-center justify-between mt-8 pt-6 border-t border-slate-100">
                {step > 1 ? (
                  <button 
                    type="button"
                    onClick={prevStep}
                    className="flex items-center gap-2 text-slate-500 font-bold hover:text-slate-800 transition-colors"
                  >
                    <ArrowLeft size={20} /> Back
                  </button>
                ) : (
                  <div></div> // Spacer
                )}

                {step < 3 ? (
                  <button 
                    type="button"
                    onClick={nextStep}
                    disabled={step === 1 && !formData.selectedPackage} // Force selection
                    className="flex items-center gap-2 px-8 py-3 bg-brand-600 text-white font-bold rounded-xl hover:bg-brand-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Next Step <ArrowRight size={20} />
                  </button>
                ) : (
                  <button 
                    type="submit"
                    disabled={isSubmitting}
                    className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white font-bold rounded-xl hover:bg-slate-800 transition-colors disabled:opacity-70 disabled:cursor-not-allowed shadow-xl shadow-brand-900/10"
                  >
                    {isSubmitting ? 'Creating Account...' : 'Create Account & Submit'}
                    {!isSubmitting && <ArrowRight size={20} />}
                  </button>
                )}
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

