                         </div>
                         <p>I agree to the <a href="#" className="text-brand-600 font-bold hover:underline">Terms of Service</a> and <a href="#" className="text-brand-600 font-bold hover:underline">Privacy Policy</a>.</p>
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Navigation Actions */}
              <div className="flex items-center justify-between mt-8 pt-6 border-t border-slate-100">
                {step > 1 ? (
                  <button 
                    type="button"
                    onClick={prevStep}
                    className="flex items-center gap-2 text-slate-500 font-bold hover:text-slate-800 transition-colors"
                  >
                    <ArrowLeft size={20} /> Back
                  </button>
                ) : (
                  <div></div> // Spacer
                )}

                {step < 3 ? (
                  <button 
                    type="button"
                    onClick={nextStep}
                    disabled={step === 1 && !formData.selectedPackage} // Force selection
                    className="flex items-center gap-2 px-8 py-3 bg-brand-600 text-white font-bold rounded-xl hover:bg-brand-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Next Step <ArrowRight size={20} />
                  </button>
                ) : (
                  <button 
                    type="submit"
                    disabled={isSubmitting}
                    className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white font-bold rounded-xl hover:bg-slate-800 transition-colors disabled:opacity-70 disabled:cursor-not-allowed shadow-xl shadow-brand-900/10"
                  >
                    {isSubmitting ? 'Creating Account...' : 'Create Account & Submit'}
                    {!isSubmitting && <ArrowRight size={20} />}
                  </button>
                )}
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StartProject;

