    { id: 'brief', label: 'Project Brief Submitted', completed: true, type: 'info' },
    { 
      id: 'call', 
      label: 'Book Kickoff Call', 
      completed: false, 
      type: 'action', 
      actionLabel: 'Book Now', 
      icon: Calendar,
      secondaryActionLabel: 'Skip & Start Async'
    },
