                    exit={{ opacity: 0 }}
                    className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm"
                    onClick={() => setViewingDoc(null)}
                >
                    <motion.div 
                        initial={{ scale: 0.95, y: 20 }}
                        animate={{ scale: 1, y: 0 }}
                        exit={{ scale: 0.95, y: 20 }}
                        className="bg-white w-full max-w-4xl h-[85vh] rounded-2xl shadow-2xl flex flex-col overflow-hidden"
                        onClick={(e) => e.stopPropagation()}
                    >
                        {/* Header */}
                        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-white rounded-lg border border-slate-200">
                                    <FileText size={20} className="text-slate-600" />
                                </div>
                                <div>
                                    <h3 className="font-bold text-slate-900">{viewingDoc.title}</h3>
                                    <p className="text-xs text-slate-500">Last updated: Oct 05, 2024</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <button onClick={() => window.alert("Printing...")} className="p-2 hover:bg-slate-200 rounded-lg text-slate-500 transition-colors">
                                    <Printer size={20} />
                                </button>
                                <button onClick={() => window.alert("Downloading...")} className="p-2 hover:bg-slate-200 rounded-lg text-slate-500 transition-colors">
                                    <Download size={20} />
                                </button>
                                <button onClick={() => setViewingDoc(null)} className="p-2 hover:bg-red-100 hover:text-red-600 rounded-lg text-slate-500 transition-colors ml-2">
                                    <X size={20} />
                                </button>
                            </div>
                        </div>

                        {/* Document Content Scroll Area */}
                        <div className="flex-1 overflow-y-auto bg-slate-100 p-8">
                            <div className="max-w-3xl mx-auto bg-white min-h-full shadow-lg p-12 md:p-16 text-slate-900 font-serif leading-relaxed">
                                {/* Letterhead */}
                                <div className="flex justify-between items-start mb-12 border-b-2 border-slate-900 pb-8">
                                    <div className="flex items-center gap-2">
                                        <div className="w-8 h-8 bg-slate-900 text-white flex items-center justify-center font-sans font-bold rounded">LP</div>
                                        <span className="font-sans font-bold text-xl tracking-tight">LocalPulse</span>
                                    </div>
                                    <div className="text-right text-sm font-sans text-slate-500">
                                        <p>123 Market St</p>
                                        <p>Design City, DC 20002</p>
                                        <p>www.localpulse.com</p>
                                    </div>
                                </div>

                                <div className="mb-8">
                                    <h1 className="text-3xl font-bold mb-2 font-sans">{viewingDoc.title}</h1>
                                    <p className="text-slate-500 font-sans">Reference: #LP-2024-8932</p>
                                </div>

                                {/* Dynamic Content based on Type */}
                                {viewingDoc.type === 'contract' ? (
                                    <div className="space-y-6">
                                        <p className="mb-6">
                                            This Service Agreement ("Agreement") is entered into as of October 5, 2024, by and between <strong>LocalPulse Agency</strong> ("Provider") and <strong>Acme Inc.</strong> ("Client").
                                        </p>

                                        <div>
                                            <h3 className="font-bold font-sans uppercase text-sm mb-2 text-slate-400">1. Scope of Work</h3>
                                            <p>The Provider agrees to deliver the web design and development services as outlined in the "{currentPlan.name}" package description. This includes the setup of 5 core pages, mobile responsiveness, and standard SEO configuration.</p>
                                        </div>

                                        <div>
                                            <h3 className="font-bold font-sans uppercase text-sm mb-2 text-slate-400">2. Payment Terms</h3>
                                            <p>The total project fee is <span className="font-bold">${currentPlan.price}.00</span>. A non-refundable deposit of <span className="font-bold">50% (${depositAmount}.00)</span> is required to commence work. The remaining balance is due upon project completion and before the final website launch.</p>
                                        </div>

                                        <div>
                                            <h3 className="font-bold font-sans uppercase text-sm mb-2 text-slate-400">3. Timeline</h3>
                                            <p>Estimated project completion is 4-6 weeks from the receipt of all necessary assets and content from the Client.</p>
                                        </div>

                                        <div>
                                            <h3 className="font-bold font-sans uppercase text-sm mb-2 text-slate-400">4. Intellectual Property</h3>
                                            <p>Upon full payment, the Client shall own all rights, title, and interest in the final website design and content.</p>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="space-y-6">
                                        <div>
                                            <h3 className="font-bold font-sans uppercase text-sm mb-2 text-slate-400">Executive Summary</h3>
                                            <p>LocalPulse proposes to redesign the Acme Inc. website to improve user engagement, modernize the brand aesthetic, and increase lead generation through optimized conversion paths.</p>
                                        </div>

                                        <div>
                                            <h3 className="font-bold font-sans uppercase text-sm mb-2 text-slate-400">Deliverables</h3>
                                            <ul className="list-disc pl-5 space-y-1">
                                                <li>Custom UI/UX Design for 5 core pages</li>
                                                <li>Mobile-first responsive development</li>
                                                <li>CMS Integration for easy content updates</li>
                                                <li>Basic On-page SEO implementation</li>
                                                <li>Contact form integration with email notifications</li>
                                            </ul>
                                        </div>

                                        <div>
                                            <h3 className="font-bold font-sans uppercase text-sm mb-2 text-slate-400">Investment</h3>
                                            <p>The selected package is the <strong>{currentPlan.name}</strong> at a total cost of <strong>${currentPlan.price}</strong>.</p>
                                        </div>
                                    </div>
                                )}

                                {/* Footer Signature Area Mock */}
                                <div className="mt-16 pt-8 border-t border-slate-200 grid grid-cols-2 gap-12">
                                    <div>
                                        <div className="h-12 border-b border-slate-900 mb-2 flex items-end pb-1">
                                            <span className="font-cursive text-2xl text-blue-900">Jane Doe</span>
                                        </div>
                                        <p className="text-xs uppercase font-bold text-slate-400">Client Signature</p>
                                    </div>
                                    <div>
                                        <div className="h-12 border-b border-slate-900 mb-2 flex items-end pb-1">
                                            <span className="font-cursive text-2xl text-slate-900">Alex Rivera</span>
                                        </div>
                                        <p className="text-xs uppercase font-bold text-slate-400">LocalPulse Representative</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                </motion.div>
            )}
        </AnimatePresence>

      </main>
    </div>
  );
};

export default Dashboard;
